'use strict';
const workspace=document.querySelector('#workspace'),dialog=document.querySelector('#seller-dialog'),dialogContent=document.querySelector('#seller-dialog-content');
let draft={title:'',description:'',category:'',price:'',location:'',images:[],status:'草稿'},page='publish',loadingImages=false,saving=false,loaded=false;
let reservation;
const escapeHTML=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=v=>new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(v);
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),3500);}
function db(){return new Promise((resolve,reject)=>{const req=indexedDB.open('campus-market-seller',1);req.onupgradeneeded=()=>req.result.createObjectStore('drafts');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function loadDraft(){const database=await db();return new Promise((resolve,reject)=>{const tx=database.transaction('drafts');const req=tx.objectStore('drafts').get('current');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);tx.oncomplete=()=>database.close();});}
async function persist(value){const database=await db();return new Promise((resolve,reject)=>{const tx=database.transaction('drafts','readwrite');tx.objectStore('drafts').put(value,'current');tx.oncomplete=()=>{database.close();resolve();};tx.onerror=()=>{database.close();reject(tx.error);};tx.onabort=()=>{database.close();reject(tx.error);};});}
function resetReservation(){const now=Date.now();reservation={status:'待卖家确认',createdAt:now-22*3600000,deadline:now+2*3600000,reason:''};}
function field(key,title,control,hint=''){return `<div class="field"><label for="${key}">${title}</label>${control}<span class="field-error" id="${key}-error"></span>${hint?`<p class="field-hint" id="${key}-hint">${hint}</p>`:''}</div>`;}
function publish(){if(!loaded){workspace.innerHTML='<p>正在读取本机保存的草稿…</p>';return;}if(draft.status==='待审核'){submitted();return;}workspace.innerHTML=`<div class="page-heading"><div><h1>给闲置一个新去处</h1><p>先留个草稿，准备好了再提交审核。</p></div><span class="status">草稿</span></div><form class="form-card" id="product-form" novalidate><div id="form-errors" class="error-summary" role="alert" tabindex="-1"></div><h2 class="form-section-title">商品信息</h2>${field('title','商品标题 <small>最多100字</small>',`<input id="title" name="title" placeholder="例如：微单相机与定焦镜头" value="${escapeHTML(draft.title)}" aria-describedby="title-error">`)}${field('description','商品描述 <small>最多2000字</small>',`<textarea id="description" name="description" placeholder="介绍一下使用情况、配件和需要留意的细节" aria-describedby="description-error">${escapeHTML(draft.description)}</textarea>`)}<div class="field-row">${field('category','商品分类',`<select id="category" name="category" aria-describedby="category-error"><option value="">请选择分类</option>${['数码电子','图书文具','生活用品','运动户外','其他'].map(v=>`<option ${draft.category===v?'selected':''}>${v}</option>`).join('')}</select>`)}${field('price','期望价格 <small>人民币 / 元</small>',`<input id="price" name="price" inputmode="decimal" placeholder="0.00" value="${escapeHTML(draft.price)}" aria-describedby="price-error price-hint">`,'大于0、不超过100000元，最多两位小数；不自动四舍五入。')}</div>${field('location','交付地点',`<input id="location" name="location" placeholder="例如：仙林校区 · 图书馆东门" value="${escapeHTML(draft.location)}" aria-describedby="location-error">`,'填写大致校内地点即可，请勿在公开描述中填写联系方式。')}<div class="field"><label for="images">商品图片 <small id="image-count">${draft.images.length}/5 张</small></label><div class="upload" id="image-upload"><input id="images" type="file" accept="image/*" multiple aria-describedby="images-error"><span class="upload-label">选择1–5张图片，第一张作为封面</span></div><span class="field-error" id="images-error"></span><div class="image-grid" id="image-grid"></div></div><div class="form-bottom"><p>草稿允许缺项，已填写的内容仍须合法。<br>审核通过后，商品才会公开并接受预约。</p><div class="form-actions"><button type="button" id="save-draft" class="btn secondary">保存草稿</button><button type="submit" class="btn primary">提交审核 ↗</button></div></div><div id="save-result" class="notice-inline" role="status" hidden></div></form>`;renderImages();}
function syncDraft(){const form=document.querySelector('#product-form');if(form)for(const key of ['title','description','category','price','location'])draft[key]=form.elements[key].value;}
function renderImages(){const grid=document.querySelector('#image-grid');if(!grid)return;grid.innerHTML=draft.images.map((im,i)=>`<div class="image-item"><img src="${escapeHTML(im.data)}" alt="商品图片${i+1}"><button type="button" data-remove="${i}" aria-label="移除第${i+1}张图片">×</button><small>${escapeHTML(im.name)}</small></div>`).join('');document.querySelector('#image-count').textContent=draft.images.length+'/5 张';}
function showErrors(errors){for(const key of ['title','description','category','price','location','images']){const input=document.getElementById(key==='images'?'image-upload':key);input?.removeAttribute('aria-invalid');const output=document.getElementById(key+'-error');if(output)output.textContent=errors[key]||'';if(errors[key])input?.setAttribute('aria-invalid','true');}const summary=document.querySelector('#form-errors');summary.textContent=Object.keys(errors).length?'请修正标出的内容，再继续操作。':'';if(Object.keys(errors).length)summary.focus();}
async function save(submit){if(saving||loadingImages){toast('图片仍在读取，请稍候再保存。');return;}syncDraft();const errors=SellerRules.validateProduct(draft,submit);showErrors(errors);if(Object.keys(errors).length)return;saving=true;const buttons=[...document.querySelectorAll('#product-form .form-actions button')];buttons.forEach(b=>b.disabled=true);try{const next={...draft,status:submit?'待审核':'草稿',savedAt:Date.now()};await persist(next);draft=next;if(submit)submitted();else{const message=document.querySelector('#save-result');message.hidden=false;message.textContent='草稿已保存到本机浏览器 · '+date(draft.savedAt)+'。刷新后可继续编辑。';}}catch{const summary=document.querySelector('#form-errors');summary.textContent='本机存储失败，尚未保存。请保留当前页面并检查浏览器存储权限或可用空间后重试。';summary.focus();}finally{saving=false;buttons.forEach(b=>b.disabled=false);}}
function submitted(){workspace.innerHTML=`<div class="page-heading"><div><h1>发布商品</h1><p>商品已送审，等待管理员处理。</p></div><span class="status">待审核</span></div><section class="submitted-card"><div class="empty-symbol" aria-hidden="true">✓</div><h2>提交成功，正在等待审核</h2><p>商品目前不对外展示，也不能被预约。审核通过后才会发布。</p><div class="steps"><span>完善信息</span><span>→</span><strong>等待审核</strong><span>→</span><span>公开发布</span></div><div class="submitted-summary"><div class="submitted-product"><img src="${escapeHTML(draft.images[0]?.data||'assets/camera.jpg')}" alt="已提交商品封面"><div><strong>${escapeHTML(draft.title)}</strong><span class="price" style="font-size:25px">¥${escapeHTML(draft.price)}</span><br><small>${escapeHTML(draft.category)} · ${escapeHTML(draft.location)}</small></div></div></div><button type="button" class="btn secondary" id="withdraw">撤回并继续编辑</button><p class="readonly-note">待审核期间如需修改，请先撤回为草稿。</p><p id="withdraw-error" role="alert"></p></section>`;}
function reservationPage(){checkExpiry();const r=reservation;workspace.innerHTML=`<div class="page-heading"><div><h1>处理预约</h1><p>认真回应每一次喜欢，给买家一个明确答复。</p></div><span class="status" id="reservation-status">${r.status}</span></div><article class="reservation-card"><div class="reservation-intro"><p>来自 <strong>林同学</strong> 的购买预约</p><span class="reservation-number">预约 R20261109-001 · 模拟</span></div><div class="reservation-product"><img src="assets/camera.jpg" alt="相机商品示意图"><div><h2>微单相机与定焦镜头</h2><small>本次预约快照价格，不随之后的商品修改变化</small><div class="price">¥1,680</div></div></div><dl class="reservation-details"><div><dt>预约创建时间 · 北京时间</dt><dd>${date(r.createdAt)}</dd></div><div><dt>确认截止时间 · 北京时间</dt><dd>${date(r.deadline)}</dd></div><div><dt>预约买家</dt><dd>林同学</dd></div><div><dt>交付地点</dt><dd>仙林校区 · 图书馆东门</dd></div></dl><div class="deadline" id="deadline-box"><div><strong id="countdown"></strong><p id="deadline-copy"></p></div><span id="deadline-label" class="modal-overline">请在截止前处理</span></div><div id="reservation-result" aria-live="polite"></div><div class="reservation-actions"><p>确认后与买家自行约定线下交付。拒绝或超时后，商品恢复已发布。</p><div class="buttons"><button type="button" class="btn secondary" id="reject-reservation">拒绝预约</button><button type="button" class="btn primary" id="confirm-reservation">确认预约</button></div></div></article><div class="rule-box"><strong>确认前，请留意这些规则</strong>确认、拒绝仅对待卖家确认的预约有效；达到截止时刻后，两项操作都会关闭。已确认的预约不能由卖家单方取消，须由参与者申请终止并由管理员核实处理。</div>`;updateReservation();}
function checkExpiry(){if(reservation.status==='待卖家确认'&&Date.now()>=reservation.deadline)reservation.status='已超时';}
function updateReservation(){checkExpiry();if(page!=='reservations')return;const r=reservation;document.querySelector('#reservation-status').textContent=r.status;const enabled=SellerRules.canHandle(r.status,Date.now(),r.deadline);for(const id of ['confirm-reservation','reject-reservation'])document.getElementById(id).disabled=!enabled;const remaining=Math.max(0,Math.ceil((r.deadline-Date.now())/1000)),h=String(Math.floor(remaining/3600)).padStart(2,'0'),m=String(Math.floor(remaining%3600/60)).padStart(2,'0'),s=String(remaining%60).padStart(2,'0');document.querySelector('#countdown').textContent=enabled?`剩余 ${h}:${m}:${s}`:r.status==='已超时'?'预约已超时':'本次预约已处理';document.querySelector('#deadline-copy').textContent=enabled?'截止时间由预约创建时起算24小时。':'确认及拒绝操作已关闭。';document.querySelector('#deadline-label').textContent=enabled?'请在截止前处理':'无需重复操作';document.querySelector('#deadline-box').classList.toggle('expired',!enabled);const result=document.querySelector('#reservation-result');if(r.status==='已确认')result.innerHTML='<div class="result-banner"><strong>预约已确认</strong><p>商品同步变为已确认。请与买家协商线下交付，交易完成由买家确认。</p></div>';if(r.status==='已拒绝')result.innerHTML=`<div class="result-banner rejected"><strong>预约已拒绝 · 商品已恢复发布</strong><p class="reason">拒绝原因：${escapeHTML(r.reason)}</p><p>处理结果将通过站内通知告知买家。</p></div>`;if(r.status==='已超时')result.innerHTML='<div class="result-banner"><strong>确认期限已到，商品已恢复发布</strong><p>预约已超时，不能再确认或拒绝。买家可重新发起新的预约。</p></div>';if(dialog.open&&!enabled){const action=dialogContent.querySelector('[data-final]');if(action)action.disabled=true;const error=dialogContent.querySelector('#decision-error');if(error)error.textContent='预约状态已变化或已到期，不能再提交。请关闭窗口查看当前状态。';}}
function openDecision(type){updateReservation();if(!SellerRules.canHandle(reservation.status,Date.now(),reservation.deadline)){toast('预约已超时或已处理，不能继续操作。');return;}const reject=type==='reject';dialogContent.innerHTML=`<div class="modal-top"><span class="modal-overline">${reject?'回应预约':'准备线下交付'}</span><button type="button" class="close" data-close aria-label="关闭">×</button></div><h2 id="dialog-title" class="modal-title">${reject?'说明拒绝的原因':'确认这次预约？'}</h2><p class="modal-copy">${reject?'买家会收到你的处理结果。拒绝后商品将恢复已发布，可接受新的预约。':'预约价格为 ¥1,680。确认后商品将进入已确认状态，不能由卖家单方面取消。'}</p>${reject?'<div class="field"><label for="reject-reason">拒绝原因 <small>必填</small></label><textarea id="reject-reason" placeholder="例如：临时无法按约定时间交付" aria-describedby="decision-error"></textarea></div>':''}<div id="decision-error" class="field-error" role="alert"></div><div class="modal-actions" style="margin-top:22px"><button type="button" class="btn secondary" data-close>暂不处理</button><button type="button" class="btn primary" data-final="${type}">${reject?'填写原因并拒绝':'确认预约'}</button></div>`;dialog.showModal();}
function render(){if(dialog.open)dialog.close();const route=location.hash.startsWith('#figmacapture=')?new URLSearchParams(location.search).get('view'):location.hash.slice(1);page=route==='reservations'?'reservations':'publish';document.querySelector('#crumb').textContent=page==='publish'?'发布商品':'处理预约';document.querySelectorAll('[data-page]').forEach(a=>{if(a.dataset.page===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.getElementById('fill-example').hidden=page!=='publish';document.getElementById('expire-now').hidden=page!=='reservations';document.getElementById('reset-reservation').hidden=page!=='reservations';document.title=(page==='publish'?'发布商品':'处理预约')+' · 校园集';page==='publish'?publish():reservationPage();}
document.addEventListener('submit',e=>{if(e.target.id==='product-form'){e.preventDefault();save(true);}});
document.addEventListener('input',e=>{if(e.target.closest('#product-form')){syncDraft();const result=document.querySelector('#save-result');if(result)result.hidden=true;}});
document.addEventListener('change',async e=>{if(e.target.id!=='images')return;const files=[...e.target.files];if(draft.images.length+files.length>5){document.querySelector('#images-error').textContent='最多选择5张图片，请减少数量后重新选择。';e.target.value='';return;}if(files.some(f=>!f.type.startsWith('image/'))){document.querySelector('#images-error').textContent='请上传图片文件。';e.target.value='';return;}loadingImages=true;try{const entries=await Promise.all(files.map(f=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>resolve({name:f.name,data:reader.result});img.onerror=reject;img.src=reader.result;};reader.onerror=reject;reader.readAsDataURL(f);})));draft.images.push(...entries);renderImages();document.querySelector('#images-error').textContent='';}catch{document.querySelector('#images-error').textContent='图片无法读取，请换一张有效图片。';}finally{loadingImages=false;e.target.value='';}});
document.addEventListener('click',async e=>{const target=e.target.closest('button');if(!target)return;if(target.dataset.remove!==undefined){draft.images.splice(Number(target.dataset.remove),1);renderImages();}if(target.id==='save-draft')save(false);if(target.id==='withdraw'){target.disabled=true;try{const next={...draft,status:'草稿'};await persist(next);draft=next;publish();}catch{document.querySelector('#withdraw-error').textContent='撤回保存失败，请重试。';target.disabled=false;}}if(target.id==='fill-example'){if(saving||loadingImages)return;if(draft.status==='待审核'){toast('请先撤回商品，再填入示例。');return;}try{const response=await fetch('assets/camera.jpg');if(!response.ok)throw new Error();const blob=await response.blob();const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob);});draft={title:'微单相机与定焦镜头',description:'记录校园生活用的相机，机身和镜头正常工作，有轻微使用痕迹。附电池、充电器及背带，可当面检查。',category:'数码电子',price:'1680',location:'仙林校区 · 图书馆东门',images:[{name:'商品示意图.jpg',data}],status:'草稿'};publish();}catch{toast('示例图片加载失败，请手动选择图片。');}}if(target.id==='confirm-reservation')openDecision('confirm');if(target.id==='reject-reservation')openDecision('reject');if(target.hasAttribute('data-close'))dialog.close();if(target.dataset.final){checkExpiry();if(!SellerRules.canHandle(reservation.status,Date.now(),reservation.deadline)){updateReservation();return;}const reason=dialogContent.querySelector('#reject-reason');if(target.dataset.final==='reject'&&!reason.value.trim()){document.querySelector('#decision-error').textContent='请填写拒绝原因，不能仅输入空格。';reason.setAttribute('aria-invalid','true');reason.focus();return;}reservation.status=target.dataset.final==='confirm'?'已确认':'已拒绝';reservation.reason=reason?.value.trim()||'';dialog.close();updateReservation();}if(target.id==='expire-now'){if(reservation.status!=='待卖家确认'){toast('当前预约已处理，请先重置示例。');return;}reservation.deadline=Date.now();reservation.createdAt=reservation.deadline-24*3600000;reservationPage();}if(target.id==='reset-reservation'){if(dialog.open)dialog.close();resetReservation();reservationPage();}});
window.addEventListener('hashchange',()=>{if(page==='publish')syncDraft();render();});
if(new URLSearchParams(location.search).has('capture'))document.body.classList.add('capture');resetReservation();render();loadDraft().then(value=>{if(value)draft=value;}).catch(()=>toast('本机草稿暂不可读取，保存时可重试。')).finally(()=>{loaded=true;if(page==='publish')publish();});setInterval(()=>{if(page==='reservations')updateReservation();},1000);
